mapper.update:
UPDATE chat_message m JOIN chat_session s ON s.merchant_id=m.merchant_id AND s.id=m.session_id
  SET m.status='STREAMING'
  WHERE  AND m.merchant_id=#{owner.merchantId} AND m.session_id=#{sessionId}
    AND m.id=#{messageId} AND m.run_id=#{runId} AND m.status='STARTED' AND s.active_run_id=#{runId}
    AND s.run_deadline_at > #{now}

UPDATE chat_message m JOIN chat_session s ON s.merchant_id=m.merchant_id AND s.id=m.session_id
SET m.sources_json=#{sourcesJson}
WHERE  AND m.merchant_id=#{owner.merchantId} AND m.session_id=#{sessionId}
  AND m.id=#{messageId} AND m.run_id=#{runId} AND s.active_run_id=#{runId}
  AND m.sender_type='ASSISTANT' AND m.status='COMPLETED'
